static const int READY_MOVES_N = 122;

// a Ready move's row by its English name (sorted by name), 0 when the table does not know it
inline const ReadyMoveRow* ready_move_row(const char* en) {
    int lo = 0, hi = READY_MOVES_N - 1;
    while (lo <= hi) { int mid = (lo + hi) >> 1; const int c = strcmp(READY_MOVES[mid].en, en);
        if (c == 0) return &READY_MOVES[mid];
        if (c < 0) lo = mid + 1; else hi = mid - 1; }
    return 0;
}
inline const char* ready_move_kind(const char* en) { const ReadyMoveRow* r = ready_move_row(en); return r ? r->kind : 0; }

